const __BasicLogoCloud = BasicLogoCloud_BasicLogoCloud;

type FeaturedLogoGrid_FeaturedBrandsLogoGridTone = "outlined" | "boxed";

type FeaturedLogoGrid_FeaturedBrandsLogoGridAlignment =
  | "left"
  | "center"
  | "right";

