export interface LogoItem {
  alt: string;
  src: string;
  width: number;
}

export interface LogoCloudProps {
  theme?: Parameters<typeof __BasicLogoCloud>[0]["theme"];
  title?: string;
  description?: string;
  logos?: LogoItem[];
  layout?: "cloud" | "grid" | "featured";
  appearance?: "plain" | "boxed" | "outlined" | "bordered";
  alignment?: "left" | "center" | "right";
  featuredIndex?: number;
  flush?: boolean;
}

const contentVariant = ({
  title,
  description,
  flush,
}: Pick<LogoCloudProps, "title" | "description" | "flush">) => {
  if (flush) {
    return "flush" as const;
  }
  if (title && description) {
    return "full" as const;
  }
  if (title) {
    return "with-title" as const;
  }
  return description ? ("with-description" as const) : "minimal";
};

const logoCloudDefinedProps = <Props extends object>(props: Props) =>
  Object.fromEntries(
    Object.entries(props).filter(([, value]) => value !== undefined)
  ) as Partial<Props>;

export const LogoCloud = ({
  theme,
  title,
  description,
  logos,
  layout = "cloud",
  appearance = "plain",
  alignment = "center",
  featuredIndex = 0,
  flush = false,
}: LogoCloudProps) => {
  const resolvedAppearance = appearance;
  const contentProps = logoCloudDefinedProps({ description, theme, title });
  if (layout === "featured") {
    return (
      <__FeaturedLogoGrid
        alignment={alignment}
        tone={resolvedAppearance === "boxed" ? "boxed" : "outlined"}
        {...contentProps}
        {...logoCloudDefinedProps({
          featuredLogo: logos?.[featuredIndex],
          supportingLogos: logos?.filter((_, index) => index !== featuredIndex),
        })}
      />
    );
  }
  if (layout === "grid") {
    return (
      <__LogosGrid
        tone={(() => {
          if (resolvedAppearance === "bordered") {
            return "bordered";
          }
          if (resolvedAppearance === "outlined") {
            return "outlined";
          }
          return "boxed";
        })()}
        {...contentProps}
        {...logoCloudDefinedProps({ logos })}
      />
    );
  }
  const variant = contentVariant({ description, flush, title });
  if (resolvedAppearance === "plain") {
    return (
      <__BasicLogoCloud
        variant={variant === "flush" ? "full" : variant}
        {...contentProps}
        {...logoCloudDefinedProps({ logos })}
      />
    );
  }
  if (resolvedAppearance === "bordered") {
    return (
      <__BorderedLogoCloud
        variant={variant}
        {...contentProps}
        {...logoCloudDefinedProps({ logos })}
      />
    );
  }
  return (
    <__LogoCloud
      tone={resolvedAppearance === "outlined" ? "outlined" : "boxed"}
      variant={variant}
      {...contentProps}
      {...logoCloudDefinedProps({ logos })}
    />
  );
};

LogoCloud.PreviewProps = {
  alignment: "center",
  appearance: "plain",
  flush: false,
  layout: "cloud",
} satisfies LogoCloudProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
